#define CONFIG_LWIP_NETBUF_RECVINFO 0
#define CONFIG_LWIP_TIMERS_ONDEMAND 0
#define CONFIG_LWIP_IPV6 0
#define CONFIG_LWIP_IPV6_MEMP_NUM_ND6_QUEUE 3
