/* Debug flags (all disabled) */
/* CONFIG_LWIP_DEBUG, CONFIG_LWIP_*_DEBUG are left undefined */

/* PPP (disabled) */
/* CONFIG_LWIP_PPP_SUPPORT is left undefined */

/* TCP oversize: use MSS by default */
#define CONFIG_LWIP_TCP_OVERSIZE_MSS 1

/* IP changes */
#define CONFIG_LWIP_TCP_KEEP_CONNECTION_WHEN_IP_CHANGES 0

/* lwIP socket API */
#define CONFIG_LWIP_SOCKET 1
#define CONFIG_LWIP_DNS 1

/* System */
#define CONFIG_ESP8266_XTAL_FREQ 26

#endif /* SDKCONFIG_H */
